/* /events/ — the weekly events page (generated by scripts/build-events-page.js).
   It reads ../events.json at runtime; tests serve a fixed feed (see
   helpers/atlas.js) because the real one is regenerated weekly and not in git. */
const { test, expect, DATA, byId, eventsFixture, ROOT } = require("./helpers/atlas");
const fs = require("fs");
const os = require("os");
const path = require("path");
const { execFileSync } = require("child_process");

test("the events page loads and lists upcoming events", async ({ page }) => {
  const feed = eventsFixture();
  await page.goto("./events/");
  await expect(page.locator("#list .ev")).toHaveCount(feed.events.length);
  await expect(page.locator("#genLine")).toContainText("refreshed");
  await expect(page.locator("#list")).toContainText(feed.events[0].title);
});

test("an event's \"on the atlas\" link opens that organization's drawer", async ({ page }) => {
  const hosted = eventsFixture().events.find(e => e.atlasId);
  await page.goto("./events/");
  await page.locator("#list a.atlas").first().click();
  await expect(page.locator("#drawer")).toHaveClass(/\bopen\b/);
  await expect(page.locator("#drName")).toHaveText(byId[hosted.atlasId].name);
});

test.describe("without events.json", () => {
  // the weekly feed can be missing (first deploy, a failed refresh); the page
  // must say so instead of hanging on "Loading events…" or throwing
  test.use({ eventsFeed: "missing", expectedHttpErrors: [/\/events\.json/] });

  test("the events page shows a fallback message and no errors", async ({ page }) => {
    await page.goto("./events/");
    await expect(page.locator("#list .empty")).toBeVisible();
    await expect(page.locator("#list")).not.toContainText("Loading events");
  });
});

// Contract 2 on the events page: its footer count comes from the data too.
// The events page ships no script, so any count lifted into its footer could only
// go stale — it read "101 organizations" for months. The clause is dropped at build
// time instead (scripts/build-events-page.js); the atlas page still shows a live
// count. This guards the drop, so a number cannot quietly return.
test("the events page footer claims no organization count", async ({ page }) => {
  await page.goto("./events/");
  await expect(page.locator("#footCount")).toHaveCount(0);
  await expect(page.locator("footer")).not.toHaveText(/\d[\d,]*\s+organi[sz]ations/i);
});

// Same for the curation month, and for the same reason: this page has no script, so
// a date lifted into it can only rot. It read "Curated June 2026" into October.
test("the events page footer claims no curation date", async ({ page }) => {
  await page.goto("./events/");
  await expect(page.locator("#footCurated")).toHaveCount(0);
  await expect(page.locator("footer")).not.toHaveText(/Curated/i);
});

// The footer band carries white partner artwork, so it has to stay dark in light mode as well.
// The atlas does that with rules outside the footer block this page's generator copies, so this
// page once showed both marks on its near-white ground. Compared across themes rather than with
// a colour value: a palette change can't break it, a light footer can.
test("the events page footer stays dark in light theme", async ({ page }) => {
  const look = () => page.evaluate(() => {
    const ground = (el) => {
      for (; el; el = el.parentElement) {
        const bg = getComputedStyle(el).backgroundColor;
        if (bg !== "rgba(0, 0, 0, 0)") return bg;
      }
      return null;
    };
    const footer = document.querySelector("footer.footer");
    return {
      page: ground(document.body),
      footer: ground(footer),
      text: getComputedStyle(footer).color,
      link: getComputedStyle(footer.querySelector("a")).color,
    };
  });
  await page.goto("./events/");
  const dark = await look();
  await page.evaluate(() => localStorage.setItem("toa-atlas-theme", "light"));
  await page.reload();
  await expect(page.locator("html")).not.toHaveClass(/\bdark\b/);
  const light = await look();
  expect(light.page, "the light theme should change the page's own ground").not.toBe(dark.page);
  expect({ footer: light.footer, text: light.text, link: light.link })
    .toEqual({ footer: dark.footer, text: dark.text, link: dark.link });
});

// The page has two tiers of secondary text: --muted for the standfirst and each event's time and
// details, --faint for the "refreshed" line in the top nav and the sources line at the foot. Faint
// is meant to read a step weaker. #65 swapped the two and #69 put them back, both on 2026-10-30,
// and no test saw either: both values cleared AA, which is all axe asks. Weaker isn't lighter or
// darker but closer to the ground (darker on the dark page, lighter on the light one), so this
// compares each tier's contrast with --bg. Each token is painted on a canvas over --bg, as its text
// is on the page, so any colour syntax works.
const luminance = (rgb) => {
  const [r, g, b] = rgb.map((v) => ((v /= 255) <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
const contrast = (a, b) => {
  const [lighter, darker] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (lighter + 0.05) / (darker + 0.05);
};

for (const theme of ["dark", "light"]) {
  test(`the events page's faint text stays a step weaker than its muted text, in ${theme} theme`, async ({ page }) => {
    // the bootstrap at the top of the page drops html's "dark" class when the stored theme is light
    if (theme === "light") {
      await page.addInitScript(() => { try { localStorage.setItem("toa-atlas-theme", "light"); } catch (e) {} });
    }
    await page.goto("./events/");
    if (theme === "light") await expect(page.locator("html")).not.toHaveClass(/\bdark\b/);
    else await expect(page.locator("html")).toHaveClass(/\bdark\b/);

    const tiers = await page.evaluate(() => {
      const probe = document.body.appendChild(document.createElement("i"));
      const ctx = document.createElement("canvas").getContext("2d", { willReadFrequently: true });
      // the colour one pixel ends up after painting --bg and then the token over it
      const tier = (token) => {
        for (const paint of ["--bg", token]) {
          probe.style.color = `var(${paint})`;
          ctx.fillStyle = getComputedStyle(probe).color;
          ctx.fillRect(0, 0, 1, 1);
        }
        return {
          value: getComputedStyle(probe).getPropertyValue(token).trim(),
          rgb: [...ctx.getImageData(0, 0, 1, 1).data.slice(0, 3)],
        };
      };
      const out = { bg: tier("--bg"), muted: tier("--muted"), faint: tier("--faint") };
      probe.remove();
      return out;
    });
    for (const token of ["bg", "muted", "faint"]) {
      expect(tiers[token].value, `the events page should define --${token}`).not.toBe("");
    }
    const muted = contrast(tiers.muted.rgb, tiers.bg.rgb), faint = contrast(tiers.faint.rgb, tiers.bg.rgb);
    const seen = `--faint ${tiers.faint.value} is ${faint.toFixed(2)}:1 and --muted ${tiers.muted.value} ` +
      `is ${muted.toFixed(2)}:1 on --bg ${tiers.bg.value}`;
    expect(faint, `faint text should sit closer to the ${theme} ground than muted text: ${seen}`).toBeLessThan(muted);
    expect(faint, `faint text should still clear WCAG AA's 4.5:1: ${seen}`).toBeGreaterThanOrEqual(4.5);
  });
}

// The footer comes from index.html, where its "Suggest an entry" link calls suggestEntry().
// This page never defines that function, so the link did nothing but throw a ReferenceError,
// and the error guard never saw it because no test clicked it. scripts/build-events-page.js
// now points the link at the suggestion form, on the repository GH_REPO names.
test("the events page footer's Suggest an entry link opens the suggestion form", async ({ page }) => {
  const html = fs.readFileSync(path.join(ROOT, "index.html"), "utf8");
  const repo = (html.match(/^const GH_REPO = "([^"]+)"/m) || [])[1];
  expect(repo, "index.html must define `const GH_REPO`").toBeTruthy();

  await page.goto("./events/");
  const link = page.locator("footer.footer a", { hasText: "Suggest an entry" });
  await expect(link).toHaveAttribute("href", `https://github.com/${repo}/issues/new?template=suggest-entry.yml`);
  await expect(link).not.toHaveAttribute("onclick");
});

// Contract: a copy of this repository must not file issues on the repository it
// was copied FROM. index.html's `const GH_REPO` is the single place that decides,
// and scripts/build-events-page.js reads it. Until 2026-10-23 this page hardcoded
// holzerjm/mass-ai-atlas in three links, so every copy's "Add your event" button
// opened an issue upstream — found by walking the hackathon setup path on a real
// template copy. This guards the wiring, not the value.
test("the events page contribution links follow index.html's GH_REPO", async ({ page }) => {
  const html = fs.readFileSync(path.join(ROOT, "index.html"), "utf8");
  const repo = (html.match(/^const GH_REPO = "([^"]+)"/m) || [])[1];
  expect(repo, "index.html must define `const GH_REPO`").toBeTruthy();

  await page.goto("./events/");
  const links = await page.locator('a[href*="/issues/new"]').evaluateAll((els) => els.map((e) => e.href));
  expect(links.length, "the events page should offer at least one contribution link").toBeGreaterThan(0);
  for (const href of links) expect(href).toContain(`github.com/${repo}/issues/new`);
});

// The same contract for the footer's link to the repository, which index.html writes into its
// HTML and points at GH_REPO only when the atlas script runs. This page runs no such script, so
// scripts/build-events-page.js sets it. Until 2026-11 a copy's events footer linked to the
// original repository. Running the generator on index.html with another GH_REPO guards the
// wiring, not the value.
test("the events page footer's GitHub link follows index.html's GH_REPO", () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "atlas-events-"));
  try {
    for (const dir of ["scripts", "events"]) fs.mkdirSync(path.join(tmp, dir));
    fs.copyFileSync(path.join(ROOT, "scripts", "build-events-page.js"), path.join(tmp, "scripts", "build-events-page.js"));
    const html = fs.readFileSync(path.join(ROOT, "index.html"), "utf8");
    const copy = html.replace(/^const GH_REPO = "[^"]+"/m, 'const GH_REPO = "example-org/atlas-copy"');
    expect(copy, "index.html must define `const GH_REPO`").not.toBe(html);
    fs.writeFileSync(path.join(tmp, "index.html"), copy);
    execFileSync(process.execPath, [path.join(tmp, "scripts", "build-events-page.js")], { stdio: "pipe" });
    const page = fs.readFileSync(path.join(tmp, "events", "index.html"), "utf8");
    expect(page).toContain('<a id="footGhLink" href="https://github.com/example-org/atlas-copy"');
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
});
